  const pattern = /(^```[^\n]*\n[\s\S]*?^```[^\n]*(?:\n|$)|^~~~[^\n]*\n[\s\S]*?^~~~[^\n]*(?:\n|$)|\$\$[\s\S]*?\$\$|\\\[[\s\S]*?\\\]|\\\([^\n]*?\\\)|(?<![\\$])\$(?!\$)[^$\n]+\$(?!\$)|!\[[^\]]*\]\([^\n]*?\)|<img\b[^>]*>|`+[^`\n]+`+)/gmi;
  const masked = text.replace(pattern, value => {
    const key = '⟦BT_KEEP_' + String(Object.keys(kept).length).padStart(5, '0') + '⟧';
